python -c "
import pandas as pd
invoices = pd.read_csv('/app/dataset/invoices.csv')

def first_digit(num):
    s = str(abs(num)).lstrip('0.')
    return int(s[0]) if s else 0

for seller, group in invoices.groupby('seller_id'):
    amounts = group['net_amount'].tolist()
    if len(amounts) > 5:
        digits = [first_digit(a) for a in amounts]
        if digits.count(9) / len(digits) > 0.5:
            print(seller, len(amounts), digits.count(9) / len(digits))
"

